        String a = "dusty";
        String b = "study";
        StringBuilder rest = new StringBuilder(b);
        boolean ok = a.length() == b.length();
        for (int i = 0; i < a.length() && ok; i++) {
            int found = rest.indexOf(String.valueOf(a.charAt(i)));
            if (found == -1) {
                ok = false;
            } else {
                rest.deleteCharAt(found);
            }
        }
        System.out.println(ok);
    }
